const regions=[['THE FORGOTTEN TEMPLE','Moderate','A sunken sanctuary surrounding the first known signal.'],['THE ABYSSAL ARCHIVE','Severe','A drowned repository beneath a lightless planetary sea.'],['THE ASHEN CITY','High','A glass-black metropolis preserved beneath metallic ash.'],['THE CELESTIAL RUINS','Extreme','Orbital monuments adrift above a fractured world.'],['THE OBSIDIAN VAULT','Unknown','A sealed chamber older than every recovered record.']];
const civs=[['NEXUS','Origin unverified'],['VESPERA','Celestial frontier'],['KHEM-RA','Ashen inner world'],['THALASS','Abyssal continuum'],['THE FIRST ONES','Record sealed']];
let account=null,selectedRegion=null;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(t.timer);t.timer=setTimeout(()=>t.classList.remove('show'),2800)}
function short(a){return a?`${a.slice(0,6)}…${a.slice(-4)}`:'Connect Wallet'}
function route(){const id=(location.hash||'#home').slice(1);const target=document.getElementById(id)||$('#home');$$('.view').forEach(v=>v.classList.toggle('active',v===target));$$('.links a').forEach(a=>a.classList.toggle('active',a.hash===`#${target.id}`));$('#walletMenu').classList.remove('show');scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}
addEventListener('hashchange',route);route();
$('.menu-btn').onclick=()=>$('.links').classList.toggle('open');$$('.links a').forEach(a=>a.onclick=()=>$('.links').classList.remove('open'));
$('#trailerBtn').onclick=()=>toast('Trailer coming soon — no video has been published.');
$('#regionGrid').innerHTML=regions.map((r,i)=>`<article class="region" data-i="${i}"><label>REGION 0${i+1}</label><h3>${r[0]}</h3><p>${r[2]}</p><small>DIFFICULTY · ${r[1]}<br>PROGRESS · UNAVAILABLE</small></article>`).join('');
$('#civilizations').innerHTML=civs.map((c,i)=>`<article class="civilization"><i>0${i+1}</i><h2>${c[0]}</h2><p>${c[1]}. Additional records unlock through verified related discoveries.</p><small>PROGRESS · UNAVAILABLE</small></article>`).join('');
$$('.region').forEach(el=>el.onclick=()=>{selectedRegion=regions[+el.dataset.i];$$('.region').forEach(x=>x.classList.toggle('selected',x===el));$('#expeditionTitle').textContent=selectedRegion[0];$('#expeditionStatus').textContent=account?'Region selected. Production expedition service is not configured in this preview.':'Connect an injected EIP-1193 wallet to continue.';$('#expeditionBtn').disabled=!account});
$('#expeditionBtn').onclick=()=>toast('Expedition unavailable: server, database, AI and image providers are not configured.');
async function connect(){if(account){$('#walletMenu').classList.toggle('show');return}if(!window.ethereum){toast('No EIP-1193 wallet detected. Install MetaMask, Rabby, or another compatible wallet.');return}try{const [a]=await ethereum.request({method:'eth_requestAccounts'});account=a;renderWallet();toast('Wallet connected. Sign-in remains required for persistent progress.')}catch(e){toast(e.code===4001?'Connection cancelled.':'Wallet connection failed.')}}
function renderWallet(){const label=short(account);$('#walletLabel').textContent=label;$('#walletBtn').classList.toggle('connected',!!account);$('#profileWallet').textContent=account||'NOT CONNECTED';$('#profileChain').textContent=account?'Browser wallet connected · persistent profile service unavailable':'Connect your wallet to load private collection data.';$('#expeditionBtn').disabled=!(account&&selectedRegion)}
$('#walletBtn').onclick=connect;
if(window.ethereum){ethereum.on?.('accountsChanged',a=>{account=a[0]||null;renderWallet();toast(account?'Active account updated.':'Wallet disconnected.');});ethereum.on?.('chainChanged',()=>toast('Network changed. Chain configuration is intentionally not guessed.'))}
$('#walletMenu').onclick=async e=>{const a=e.target.dataset.action;if(!a)return;if(a==='profile')location.hash='profile';if(a==='copy'&&account){await navigator.clipboard.writeText(account);toast('Address copied.')}if(a==='switch')toast('Robinhood Chain configuration is unavailable until verified official settings are supplied.');if(a==='disconnect'){account=null;renderWallet();toast('Local session disconnected. Disconnect the site in your wallet to revoke permissions.')}$('#walletMenu').classList.remove('show')};
$$('#leaderTabs button').forEach(b=>b.onclick=()=>{$$('#leaderTabs button').forEach(x=>x.classList.toggle('active',x===b));toast(`${b.textContent}: no verified records yet.`)});
